UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"poised adult goddess with prominent necklace and sweeping feathered mantle","appearance":{"face":["clearly adult confident face with warm commanding gaze"],"body":["strong graceful adult build"]},"costumeLanguage":["layered northern ceremonial dress and cloak centered on Brísingamen"],"paletteCues":["warm gold"],"temperament":["confident","sensual","warrior-poised"],"mythologicalFacts":["goddess associated with love, fertility, seiðr and the slain"],"originalDesignChoices":["Keep glamour grounded in northern textiles and metalwork, not generic fantasy lingerie."],"avoid":["specific modern franchise likeness","youth-coded sexualization"],"canonicalPrompt":"Depict Freyja as an original MythCanvas interpretation. Preserve Brísingamen necklace, falcon-feather motif, cat-drawn chariot motif; keep poised adult goddess with prominent necklace and sweeping feathered mantle. Use layered northern ceremonial dress and cloak centered on Brísingamen. Maintain a confident presence."}') WHERE id = 'character-freyja';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"tall lean elder god with one-eyed profile, long spear and paired ravens","appearance":{"face":["aged one-eyed face with severe intelligent gaze"],"body":["lean weathered elder build"]},"costumeLanguage":["layered traveller-warrior cloak with subtle royal metalwork and rune details"],"paletteCues":["raven black"],"temperament":["inscrutable","wise","ruthless"],"mythologicalFacts":["chief god associated with wisdom, war, poetry and magic"],"originalDesignChoices":["Make him a dangerous wandering king-sage, not a horned fantasy wizard."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Odin as an original MythCanvas interpretation. Preserve single eye, Gungnir spear, two ravens; keep tall lean elder god with one-eyed profile, long spear and paired ravens. Use layered traveller-warrior cloak with subtle royal metalwork and rune details. Maintain a inscrutable presence."}') WHERE id = 'character-odin';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"broad powerful adult thunder god with compact hammer held close to the body","appearance":{"face":["rugged adult face with direct protective expression"],"body":["very strong stocky athletic build"]},"costumeLanguage":["practical northern tunic, mail and leather with a heavy red cloak"],"paletteCues":["storm red"],"temperament":["protective","boisterous","steadfast"],"mythologicalFacts":["thunder god and protector figure"],"originalDesignChoices":["Keep Mjölnir compact and hammer-like; avoid modern superhero costume geometry."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Thor as an original MythCanvas interpretation. Preserve Mjölnir hammer, red beard, lightning; keep broad powerful adult thunder god with compact hammer held close to the body. Use practical northern tunic, mail and leather with a heavy red cloak. Maintain a protective presence."}') WHERE id = 'character-thor';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"lean adult trickster with asymmetrical cloak movement and fluid transforming edges","appearance":{"face":["sharp adult features with intelligent ambiguous expression"],"body":["lean agile adult build"]},"costumeLanguage":["well-made northern layered clothing with asymmetrical fastening and restrained knotwork"],"paletteCues":["ember green"],"temperament":["clever","ambiguous","restless"],"mythologicalFacts":["trickster and shape-shifter central to many Norse myths"],"originalDesignChoices":["Do not default to green-and-gold modern franchise styling; transformation cues should remain mythological and subtle."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Loki as an original MythCanvas interpretation. Preserve shape-shifting motif, subtle fire, binding chains as fate motif; keep lean adult trickster with asymmetrical cloak movement and fluid transforming edges. Use well-made northern layered clothing with asymmetrical fastening and restrained knotwork. Maintain a clever presence."}') WHERE id = 'character-loki';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"stately mature goddess with long mantle, spindle and key-bearing belt","appearance":{"face":["mature composed face with inward knowing gaze"],"body":["graceful mature adult build"]},"costumeLanguage":["high-status northern gown and mantle with fine tablet-woven borders"],"paletteCues":["cloud white"],"temperament":["maternal","reserved","far-seeing"],"mythologicalFacts":["wife of Odin and associated with marriage and foreknowledge"],"originalDesignChoices":["Keep her distinct from Freyja by emphasizing queenly stillness and household sovereignty rather than glamour."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Frigg as an original MythCanvas interpretation. Preserve spindle, keys, queenly mantle; keep stately mature goddess with long mantle, spindle and key-bearing belt. Use high-status northern gown and mantle with fine tablet-woven borders. Maintain a maternal presence."}') WHERE id = 'character-frigg';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"youthful-adult noble god in a clear luminous silhouette with no heavy armor","appearance":{"face":["bright youthful-adult face with gentle open expression"],"body":["tall lean adult build"]},"costumeLanguage":["fine pale northern tunic and cloak with restrained gold brooches"],"paletteCues":["winter white"],"temperament":["gentle","noble","tragic"],"mythologicalFacts":["beloved god whose death is caused through mistletoe"],"originalDesignChoices":["Avoid angel wings or Christian saint imagery; luminosity should stay within Norse visual language."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Baldr as an original MythCanvas interpretation. Preserve radiant pale light, mistletoe, funeral ship; keep youthful-adult noble god in a clear luminous silhouette with no heavy armor. Use fine pale northern tunic and cloak with restrained gold brooches. Maintain a gentle presence."}') WHERE id = 'character-baldr';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"upright sentinel with horn and spear-like vertical rhythm overlooking a bridge","appearance":{"face":["focused adult face with exceptionally alert gaze"],"body":["tall athletic adult build"]},"costumeLanguage":["bright functional northern mail and cloak with high-quality metalwork"],"paletteCues":["rainbow frost"],"temperament":["vigilant","disciplined","unyielding"],"mythologicalFacts":["watchman of the gods and guardian associated with Bifröst"],"originalDesignChoices":["Rainbow effects must remain atmospheric and architectural, not become a colorful superhero costume."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Heimdall as an original MythCanvas interpretation. Preserve Gjallarhorn, Bifröst, watchman stance; keep upright sentinel with horn and spear-like vertical rhythm overlooking a bridge. Use bright functional northern mail and cloak with high-quality metalwork. Maintain a vigilant presence."}') WHERE id = 'character-heimdall';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"one-handed warrior-god standing squarely with sword and an intentionally visible missing hand","appearance":{"face":["stern adult face with direct honorable gaze"],"body":["athletic adult warrior build"]},"costumeLanguage":["plain high-quality northern war gear with oath-ring details"],"paletteCues":["iron blue"],"temperament":["honorable","courageous","austere"],"mythologicalFacts":["god strongly associated with law, oaths and battle"],"originalDesignChoices":["Do not replace the missing hand with a magical prosthetic in canonical form."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Tyr as an original MythCanvas interpretation. Preserve missing hand, sword, oath motif; keep one-handed warrior-god standing squarely with sword and an intentionally visible missing hand. Use plain high-quality northern war gear with oath-ring details. Maintain a honorable presence."}') WHERE id = 'character-tyr';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"open relaxed adult god with golden boar beside a broad harvest-and-sun silhouette","appearance":{"face":["warm adult face with peaceful confident expression"],"body":["healthy athletic adult build"]},"costumeLanguage":["prosperous Vanir clothing with fine wool, cloak and restrained gold fittings"],"paletteCues":["harvest gold"],"temperament":["benevolent","prosperous","peaceful"],"mythologicalFacts":["Vanir god associated with fertility, prosperity and fair weather"],"originalDesignChoices":["Avoid turning him into a generic elf prince; keep agrarian prosperity and Vanir identity central."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Freyr as an original MythCanvas interpretation. Preserve golden boar Gullinbursti, fertility, sunlight; keep open relaxed adult god with golden boar beside a broad harvest-and-sun silhouette. Use prosperous Vanir clothing with fine wool, cloak and restrained gold fittings. Maintain a benevolent presence."}') WHERE id = 'character-freyr';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"tall still female ruler whose body shows a controlled living/death duality without gore","appearance":{"face":["clearly adult face with one healthy side and one pallid death-marked side"],"body":["slender adult build with rigid sovereign posture"]},"costumeLanguage":["dark layered northern gown with bone-pale and iron-grey textile contrast"],"paletteCues":["frost black"],"temperament":["cold","remote","sovereign"],"mythologicalFacts":["ruler of Hel, realm of many of the dead"],"originalDesignChoices":["No gore, zombie decay or horror makeup; preserve solemn underworld sovereignty."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Hel as an original MythCanvas interpretation. Preserve half-living half-death bodily contrast, underworld throne, cold realm; keep tall still female ruler whose body shows a controlled living/death duality without gore. Use dark layered northern gown with bone-pale and iron-grey textile contrast. Maintain a cold presence."}') WHERE id = 'character-hel';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"colossal wolf with low predatory body line and broken-binding tension","appearance":{"face":["intelligent feral wolf face with oversized but natural canid jaws"],"body":["massive anatomically coherent wolf body"]},"costumeLanguage":["no humanoid clothing; use only mythic bindings and minimal symbolic metalwork"],"paletteCues":["storm charcoal"],"temperament":["feral","relentless","doom-laden"],"mythologicalFacts":["monstrous wolf son of Loki"],"originalDesignChoices":["Keep him a wolf, not a werewolf or armored game monster; scale and chain tension carry the drama."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Fenrir as an original MythCanvas interpretation. Preserve enormous wolf, binding chain Gleipnir, rune-carved restraint motif; keep colossal wolf with low predatory body line and broken-binding tension. Use no humanoid clothing; use only mythic bindings and minimal symbolic metalwork. Maintain a feral presence."}') WHERE id = 'character-fenrir';
UPDATE characters SET canonical_design_json = json_patch(COALESCE(canonical_design_json,'{}'), '{"silhouette":"immense sea serpent whose body arcs beyond the frame to imply world-encircling scale","appearance":{"face":["reptilian serpent head with ancient, non-draconic proportions"],"body":["colossal limbless serpent body with heavy ocean-worn scales"]},"costumeLanguage":["no armor; subtle rune-like natural scale pattern only"],"paletteCues":["deep ocean green"],"temperament":["ancient","implacable","catastrophic"],"mythologicalFacts":["world serpent who encircles Midgard"],"originalDesignChoices":["Do not add dragon wings, limbs or East Asian dragon anatomy."],"avoid":["generic leather-bikini fantasy","specific modern franchise likeness"],"canonicalPrompt":"Depict Jörmungandr as an original MythCanvas interpretation. Preserve world-encircling serpent, ocean, vast scale; keep immense sea serpent whose body arcs beyond the frame to imply world-encircling scale. Use no armor; subtle rune-like natural scale pattern only. Maintain a ancient presence."}') WHERE id = 'character-jormungandr';
